
import { Component, ElementRef, EventEmitter, Input, Output, ViewChild } from '@angular/core';
import { Popover } from 'bootstrap';

export interface Button {
  style?: ButtonStyle;
  text?: string;
}

export interface ButtonStyle {
  div?: string;
  button?: string;
  icon?: string;
}

@Component({
    selector: 'app-button',
    imports: [],
    templateUrl: './button.component.html',
    styleUrl: './button.component.css'
})
export class ButtonComponent {
  @Input() style: ButtonStyle | undefined
  @Input() text?: string | undefined
  @Input() disabled: boolean = false
  @Input() defaultButtonClass: string = 'btn btn-primary'
  @Input() defaultIconClass?: string
  @Input() title?: string
  @Input() sm?:boolean=false
  @Output() clickButtonEvent = new EventEmitter<void>()
  popover?: Popover

  @ViewChild('button') button!: ElementRef;

  ngAfterViewInit() {
    this.popover =new Popover(this.button.nativeElement);
  }
  ngOnDestroy(){
    this.popover?.hide()
  }
}
